with first1000 as (select "playerId" pid from rosters where "seasonId"=20262027 and is_current=true limit 1000), runs as (select run_id, as_of_date, created_at::date c from forge_runs where run_id in ('26373189-3ebd-4380-b4f4-c6797d469ca9','fb43a962-a1db-4a91-a65b-f22532eb7a11','6b37dea6-1c6b-41ec-8a55-8ddb5fb8c4f3') or (as_of_date='2026-11-15' and created_at::date='2026-11-09')) select r.as_of_date, r.c created, count(*) rows, count(*) filter (where f.pid is null) outside_first_1000, count(*) filter (where not exists (select 1 from rosters x where x."playerId"=p.player_id and x."seasonId"=20262027 and x.is_current)) not_current_roster from runs r join forge_player_projections p on p.run_id=r.run_id and p.horizon_games=1 left join first1000 f on f.pid=p.player_id group by 1,2 order by 1,2
